/* Restricted row formula parser. No eval, no external access. */
(()=>{
function compile(source, allowed){
 const s=String(source).trim().replace(/^=/,''); if(!s||s.length>300)throw Error('Formula must contain 1–300 characters');
 const tokens=[];let i=0;while(i<s.length){const m=/^\s*(?:\[([\w:-]+)\]|(\d+(?:\.\d*)?|\.\d+)|([A-Za-z]+)|([+\-*/^(),]))/.exec(s.slice(i));if(!m){if(!s.slice(i).trim())break;throw Error('Invalid formula near '+s.slice(i,i+15))}i+=m[0].length;tokens.push(m[1]?['ref',m[1]]:m[2]?['num',Number(m[2])]:m[3]?['fn',m[3].toUpperCase()]:[m[4],m[4]])}let at=0;const peek=()=>tokens[at]?.[0],take=t=>{if(peek()!==t)throw Error('Expected '+t);return tokens[at++][1]};
 const funcs={SUM:a=>a.reduce((x,y)=>x+y,0),AVERAGE:a=>a.reduce((x,y)=>x+y,0)/a.length,MIN:a=>Math.min(...a),MAX:a=>Math.max(...a),ABS:a=>Math.abs(a[0]),ROUND:a=>{if(!Number.isInteger(a[1])||Math.abs(a[1])>10)throw Error('Invalid rounding digits');const p=10**a[1];return Math.round(a[0]*p)/p}};
 function primary(){if(peek()==='num'){const n=take('num');return ()=>n}if(peek()==='ref'){const key=take('ref');if(!allowed.has(key))throw Error('Unknown field ['+key+']');return get=>{const v=get(key);if(v===null||v===undefined||String(v).trim()==='')throw Error('blank');if(typeof v==='boolean'||!Number.isFinite(Number(v)))throw Error('not numeric');return Number(v)}}if(peek()==='('){take('(');const p=expr();take(')');return p}if(peek()==='fn'){const f=take('fn');if(!Object.hasOwn(funcs,f))throw Error('Unsupported function '+f);take('(');const a=[expr()];while(peek()===','){take(',');a.push(expr())}take(')');if(f==='ABS'&&a.length!==1||f==='ROUND'&&a.length!==2)throw Error('Wrong argument count');return g=>funcs[f](a.map(x=>x(g)))}throw Error('Expected number, field or function')}
 function power(){const a=primary();if(peek()==='^'){take('^');const b=unary();return g=>a(g)**b(g)}return a}function unary(){if(peek()==='-'||peek()==='+'){const op=tokens[at++][0],a=unary();return g=>op==='-'?-a(g):a(g)}return power()}function mul(){let a=unary();while(peek()==='*'||peek()==='/'){const op=tokens[at++][0],b=unary(),p=a;a=g=>op==='*'?p(g)*b(g):p(g)/b(g)}return a}function expr(){let a=mul();while(peek()==='+'||peek()==='-'){const op=tokens[at++][0],b=mul(),p=a;a=g=>op==='+'?p(g)+b(g):p(g)-b(g)}return a}
 const f=expr();if(at!==tokens.length)throw Error('Unexpected token');return get=>{try{const n=f(get);return Number.isFinite(n)?n:'#ERROR'}catch(e){return e.message==='blank'?'':'#ERROR'}};
}
function parseTSV(s){const out=[];let row=[],v='',quoted=false;for(let i=0;i<s.length;i++){const ch=s[i];if(quoted){if(ch==='"'){if(s[i+1]==='"'){v+='"';i++}else quoted=false}else v+=ch}else if(ch==='"'&&!v)quoted=true;else if(ch==='\t'){row.push(v);v=''}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&s[i+1]==='\n')i++;row.push(v);out.push(row);row=[];v=''}else v+=ch}if(v||row.length||!out.length){row.push(v);out.push(row)}return out}
function toTSV(rows){return rows.map(r=>r.map(v=>{v=String(v??'');return /[\t\r\n"]/.test(v)?'"'+v.replaceAll('"','""')+'"':v}).join('\t')).join('\r\n')}
globalThis.LifeCareSheet={compile,parseTSV,toTSV};
})();
